<?php
defined('ABSPATH')||exit;
final class ThreePM_Fan_Insights {
 static function approved($uid){return class_exists('ThreePM_Market')&&ThreePM_Market::approved($uid);}
 static function boot(){add_action('init',[__CLASS__,'install']);add_action('wp_enqueue_scripts',[__CLASS__,'assets']);add_action('wp_ajax_threepm_fan_begin',[__CLASS__,'begin']);add_action('wp_ajax_threepm_fan_tick',[__CLASS__,'tick']);}
 static function table(){global $wpdb;return $wpdb->prefix.'threepm_fan_days';}
 static function sessions(){global $wpdb;return $wpdb->prefix.'threepm_fan_sessions';}
 static function install(){if(get_option('threepm_fan_schema')==='1')return;global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();$t=self::table();$s=self::sessions();
 dbDelta("CREATE TABLE $t (user_id bigint(20) unsigned NOT NULL, post_id bigint(20) unsigned NOT NULL, track varchar(64) NOT NULL, day date NOT NULL, streams bigint(20) unsigned NOT NULL DEFAULT 0, seconds bigint(20) unsigned NOT NULL DEFAULT 0, PRIMARY KEY  (user_id,post_id,track,day)) ENGINE=InnoDB $c;");
 dbDelta("CREATE TABLE $s (user_id bigint(20) unsigned NOT NULL, token char(64) NOT NULL, post_id bigint(20) unsigned NOT NULL, track varchar(64) NOT NULL, elapsed int unsigned NOT NULL DEFAULT 0, started bigint(20) unsigned NOT NULL, last_at bigint(20) unsigned NOT NULL, PRIMARY KEY  (user_id)) ENGINE=InnoDB $c;");
 if(!$wpdb->last_error){update_option('threepm_fan_schema','1',false);add_option('threepm_fan_since',gmdate('c'),'','no');}}
 static function assets(){if(!is_user_logged_in())return;wp_enqueue_script('threepm-fan-listening',plugin_dir_url(__FILE__).'assets/fan-listening.js',[],'1.1.5',true);wp_add_inline_script('threepm-fan-listening','window.threepmFan='.wp_json_encode(['endpoint'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('threepm_fan')]).';','before');}
 static function auth(){check_ajax_referer('threepm_fan','nonce');if(!is_user_logged_in())wp_send_json_error(null,401);return get_current_user_id();}
 static function begin(){ $uid=self::auth();if(!class_exists('ThreePM_Engagement_Tracking'))wp_send_json_error(null,503);$match=ThreePM_Engagement_Tracking::source(wp_unslash($_POST['source']??''));if(!$match||get_post_type($match['post'])!=='release')wp_send_json_error(null,404);
 global $wpdb;$table=self::sessions();$token=bin2hex(random_bytes(24));$now=time();$ok=$wpdb->query($wpdb->prepare("INSERT INTO $table (user_id,token,post_id,track,elapsed,started,last_at) VALUES (%d,%s,%d,%s,0,%d,%d) ON DUPLICATE KEY UPDATE token=VALUES(token),post_id=VALUES(post_id),track=VALUES(track),elapsed=0,started=VALUES(started),last_at=VALUES(last_at)",$uid,hash('sha256',$token),$match['post'],$match['track'],$now,$now));if($ok===false)wp_send_json_error(null,503);wp_send_json_success(['token'=>$token]);}
 static function delta($old,$reported,$wall){return max(0,min(30,$reported-$old,max(0,$wall)));}
 static function tick(){ $uid=self::auth();$token=(string)($_POST['token']??'');if(!preg_match('/^[a-f0-9]{48}$/D',$token))wp_send_json_error(null,400);$reported=absint($_POST['seconds']??0);global $wpdb;$s=self::sessions();$t=self::table();$wpdb->query('START TRANSACTION');
 try{$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $s WHERE user_id=%d FOR UPDATE",$uid),ARRAY_A);if(!$row||!hash_equals($row['token'],hash('sha256',$token))||time()-(int)$row['started']>14400)throw new RuntimeException('Session expired.');
 $delta=self::delta((int)$row['elapsed'],$reported,time()-(int)$row['last_at']);$elapsed=(int)$row['elapsed']+$delta;$stream=(int)$row['elapsed']<30&&$elapsed>=30?1:0;
 if($delta&&$wpdb->query($wpdb->prepare("INSERT INTO $t (user_id,post_id,track,day,streams,seconds) VALUES (%d,%d,%s,%s,%d,%d) ON DUPLICATE KEY UPDATE streams=streams+VALUES(streams),seconds=seconds+VALUES(seconds)",$uid,$row['post_id'],$row['track'],wp_date('Y-m-d'),$stream,$delta))===false)throw new RuntimeException('Measurement failed.');
 if($wpdb->update($s,['elapsed'=>$elapsed,'last_at'=>time()],['user_id'=>$uid],['%d','%d'],['%d'])===false)throw new RuntimeException('Measurement failed.');$wpdb->query('COMMIT');wp_send_json_success(['seconds'=>$elapsed]);
 }catch(Throwable $e){$wpdb->query('ROLLBACK');wp_send_json_error(['message'=>$e->getMessage()],409);}}
 static function metrics($uid,$period){global $wpdb;$since=ThreePM_Account_Insights::since($period);$t=self::table();$where=$wpdb->prepare('user_id=%d',$uid);if($since)$where.=$wpdb->prepare(' AND day >= %s',wp_date('Y-m-d',$since));$totals=$wpdb->get_row("SELECT COALESCE(SUM(streams),0) streams,COALESCE(SUM(seconds),0) seconds FROM $t WHERE $where",ARRAY_A);$seconds=(int)($totals['seconds']??0);
 $level=function_exists('pmpro_getMembershipLevelForUser')?pmpro_getMembershipLevelForUser($uid):false;$tier=$level?$level->name:'Free fan';$age='Not subscribed';if($level&&!empty($level->startdate)){$start=is_numeric($level->startdate)?(int)$level->startdate:strtotime($level->startdate);if($start)$age=wp_date(get_option('date_format'),$start);}
 $purchases=0;if(function_exists('wc_get_orders')){$args=['customer_id'=>$uid,'status'=>['processing','completed'],'limit'=>100,'paginate'=>true,'page'=>1];if($since)$args['date_paid']='>='.$since;do{$batch=wc_get_orders($args);foreach($batch->orders as $order)if($order->get_date_paid()&&(float)$order->get_total_refunded()<(float)$order->get_total())$purchases++;$args['page']++;}while($args['page']<=$batch->max_num_pages);}
 $artists=[];$rows=$wpdb->get_results("SELECT post_id,SUM(streams) amount FROM $t WHERE $where GROUP BY post_id HAVING amount>0",ARRAY_A);foreach($rows as $r){$owner=(int)get_post_meta($r['post_id'],'_threepm_artist_owner',true);if(!$owner)continue;$a=ThreePM_Market::account($owner);$id=(int)($a['data']['profile_id']??0);if($id&&get_post_status($id)==='publish')$artists[$id]=($artists[$id]??0)+(int)$r['amount'];}arsort($artists);$names=[];foreach(array_slice(array_keys($artists),0,3)as $id)$names[]=get_the_title($id);
 $note='3PM listening recorded since '.wp_date(get_option('date_format'),strtotime(get_option('threepm_fan_since',gmdate('c')))).'.';return [
 'membership'=>['label'=>'Membership tier','value'=>$tier,'note'=>'Your current membership.'],
 'songs'=>['label'=>'Songs streamed','value'=>number_format_i18n((int)($totals['streams']??0)),'note'=>'Plays with at least 30 seconds listened. '.$note],
 'listening'=>['label'=>'Listening time','value'=>floor($seconds/3600).'h '.floor(($seconds%3600)/60).'m','note'=>'Actual playback time; pauses and seeking excluded.'],
 'purchases'=>['label'=>'Purchases made','value'=>number_format_i18n($purchases),'note'=>'Paid orders, excluding fully refunded purchases.'],
 'membership_age'=>['label'=>'Member Since','value'=>$age,'note'=>'Start date of your current membership.'],
 'favourites'=>['label'=>'Your 3 favourite artists','value'=>$names?implode("\n",$names):'Start listening','note'=>'Ranked by your qualifying 3PM song plays.'],
 ];}
 static function screen(){ $uid=get_current_user_id();$artist=self::approved($uid);$mode=sanitize_key($_GET['dashboard_view']??($artist?'artist':'fan'));if(!in_array($mode,['artist','fan'],true))$mode=$artist?'artist':'fan';
 echo '<nav class="threepm-dashboard-toggle" aria-label="Dashboard view">';foreach(['fan'=>'Fan Dashboard','artist'=>'Artist Dashboard']as $key=>$label)echo '<a href="'.esc_url(add_query_arg('dashboard_view',$key,wc_get_page_permalink('myaccount'))).'" '.($mode===$key?'aria-current="page" style="color:#101711!important;-webkit-text-fill-color:#101711!important"':'').'>'.$label.'</a>';echo '</nav>';
 if($mode==='artist'){if($artist)ThreePM_Account_Insights::artist_screen();else echo '<section class="threepm-insights"><h2>Become a 3PM artist</h2><p>Request artist access to publish your work and see your artist statistics.</p><a class="button" href="'.esc_url(wc_get_account_endpoint_url('artist-dashboard')).'">Request artist access</a></section>';return;}
 $period=ThreePM_Account_Insights::period(get_user_meta($uid,'_threepm_fan_period',true));$metrics=self::metrics($uid,$period);$saved=(array)get_user_meta($uid,'_threepm_fan_layout',true);$order=array_values(array_unique(array_merge(array_intersect($saved,array_keys($metrics)),array_keys($metrics))));$metrics=array_replace(array_fill_keys($order,[]),$metrics);echo '<section class="threepm-insights" data-insights data-mode="fan" data-endpoint="'.esc_url(admin_url('admin-ajax.php')).'" data-nonce="'.esc_attr(wp_create_nonce('threepm_insights')).'"><header><div><p class="insight-eyebrow">YOUR 3PM LISTENING</p><h2>Fan Dashboard</h2></div><label>Time period<select data-insight-period>';foreach(['all'=>'All time','30'=>'Last 30 days','60'=>'Last 60 days','90'=>'Last 90 days']as $key=>$label)echo '<option value="'.$key.'" '.selected($period,(string)$key,false).'>'.$label.'</option>';echo '</select></label></header><div class="insight-grid">';foreach($metrics as $key=>$m){echo '<article class="insight-tile" data-metric="'.$key.'" draggable="true"><div class="insight-tile-head"><h3>'.esc_html($m['label']).'</h3>';if($key==='membership')echo '<svg class="threepm-membership-shield" viewBox="0 0 32 36" aria-hidden="true"><path d="M16 2 29 7v10c0 8-6 13-13 17C9 30 3 25 3 17V7Z"/><path d="m10 17 4 4 8-9"/></svg>';echo '<span aria-hidden="true" class="insight-grip">⠿</span></div><strong class="insight-value">'.esc_html($m['value']).'</strong><p class="insight-note">'.esc_html($m['note']).'</p><div class="insight-move"><button type="button" data-move="-1" aria-label="Move '.esc_attr($m['label']).' earlier">←</button><button type="button" data-move="1" aria-label="Move '.esc_attr($m['label']).' later">→</button></div></article>';}echo '</div><p role="status" data-insight-status></p><button type="button" data-insight-retry hidden>Retry</button></section>';
 }
}
ThreePM_Fan_Insights::boot();
